DATA.cards = [
/* ===== Modul 1: Bildmittel ===== */
{m:"m1", g:"Bildmittel", f:"In welche vier Bereiche gliedern sich die bildsprachlichen Mittel?", b:"1. Linien und Flächen · 2. Farbe · 3. Bildraum · 4. Komposition / Bildaufbau. In Kunstwerken wirken diese vier Bereiche eng zusammen – ihre Wechselbeziehungen müssen bei der Analyse beachtet werden."},
{m:"m1", g:"Bildmittel", f:"Warum analysiert man überhaupt die Bildmittel?", b:"Weil die inhaltliche Aussage eines Werks (das WARUM) untrennbar mit seiner Form (dem WIE) verknüpft ist. Die Wirkung eines Gemäldes entsteht durch die gestaltenden Entscheidungen des Künstlers – den Einsatz der Bildmittel."},
{m:"m1", g:"Punkt", f:"Was ist der Punkt und welche Funktionen hat er?", b:"Die kleinste wahrgenommene Einheit. Anordnungen: Reihung, Raster, Streuung, Ballung. Viele aneinandergesetzte Punkte werden als Muster, Struktur oder Licht-Schatten-Modellierung wahrgenommen."},
{m:"m1", g:"Linie", f:"In welchen Erscheinungsformen kann eine Linie auftreten?", b:"Als Kontur-/Umrisslinie (outline), offene Linie, Binnenlinie (z. B. Teil einer Kreuz- oder Parallelschraffur), dekorative/ornamentale/arabeske Linie (schmückende Funktion) oder autonome Linie (ohne Gegenstandsbezug)."},
{m:"m1", g:"Linie", f:"Wie wirken die vier Grundrichtungen von Linien?", b:"Senkrecht = statisch, standhaft, fest · Waagerecht = ruhig, weit (z. B. Horizont, betont den Betrachterstandpunkt) · Schräg/Fluchtlinien = dynamisch, blickführend, raumtiefeerzeugend · Gebogen = bewegt, lebendig (z. B. Regenschirme: beschützend)."},
{m:"m1", g:"Fläche", f:"Was definiert eine Fläche und welche Flächenformen gibt es?", b:"Eine Fläche wird durch Farben und Linien begrenzt und definiert. Ihre Form kann geometrisch (konstruiert), organisch (von der Natur abgeleitet) oder frei entwickelt sein."},
{m:"m1", g:"Fläche", f:"Nenne fünf Möglichkeiten der Flächenausgestaltung.", b:"1. Gleichmäßiges Einfärben mit einem Ton (flächig) · 2. Variierende Farbgestaltung mit hellen/dunklen Zonen (plastisch, Licht-Schatten-Modellierung) · 3. Ineinanderfließen von Farbtönen · 4. Ornamenthafte Gestaltung mit Punkten, Linien, Strukturen · 5. Nachempfinden der Stofflichkeit (Materialität)."},
{m:"m1", g:"Fläche", f:"Nach welchen Aspekten beurteilt man Flächenformen in der Analyse?", b:"Quantität (Größen- und Mengenverhältnisse), Qualität (regulier–unreguliert, geöffnet–geschlossen, rund–eckig, einfach–komplex), Begrenzung (scharf–unscharf/diffus, offen–geschlossen), Richtungsbezüge. Bildspannung entsteht durch Kontraste der Formen."},
{m:"m1", g:"Komposition", f:"Was ist Komposition?", b:"Die unmittelbar erkennbare Grundstruktur eines Kunstwerkes. Die Anordnung der Bildteile (Format, Linien, Positionen, Proportionen) bestimmt die Wirkung und die Bildaussage mit."},
{m:"m1", g:"Komposition", f:"Nenne die Aspekte, nach denen man eine Komposition analysiert.", b:"Bildformat · Richtungen (horizontal, vertikal, diagonal) · Kompositionsfiguren (Dreieck, Kreis, Oval) · Position (zentral/dezentral) · Ordnungsprinzipien · Proportionen (Goldener Schnitt) · Bewegungstendenz · statische vs. dynamische Komposition."},
{m:"m1", g:"Ordnungsprinzipien", f:"Was sind Ordnungsprinzipien der Komposition?", b:"Reihung, Ballung, Streuung, Gruppierung, Rhythmus, Orthogonalität sowie Symmetrie (mit Symmetrieachse) ↔ Asymmetrie."},
{m:"m1", g:"Goldener Schnitt", f:"Was ist der Goldene Schnitt – Verhältnis und Wirkung?", b:"Ein Proportionsverhältnis von 1 : 1,618 (ca. 3/8 zu 5/8). Liegt ein Bildelement im goldenen Schnitt, wirkt die Komposition harmonisch und ausgewogen."},
{m:"m1", g:"Kompositionsfigur", f:"Welche Bedeutungen haben Kompositionsfiguren traditionell?", b:"Halbkreis und Kreis = Vollkommenheit des Himmels · Dreieck = göttliche Dreifaltigkeit (Dreiecks-/Keilkomposition wirkt zudem fest und statisch, diagonale Dreiecke auch dynamisch)."},
{m:"m1", g:"Kompositionsskizze", f:"Was ist eine Kompositionsskizze?", b:"Eine Skizze, in der die wichtigsten Kompositionslinien (Hilfslinien) nachgezeichnet werden. Sie können auch fiktiv sein – z. B. durch Blickpunkte und Blickrichtungen, die das Auge des Betrachters lenken."},
{m:"m1", f:"Woran macht man eine statische vs. eine dynamische Komposition fest?", b:"Statische Komposition (viele Senkrechte/Waagerechte, Symmetrie) = ruhige Wirkung · Dynamische Komposition (Diagonalen, Asymmetrie, Fluchtlinien) = unruhige, bewegte Wirkung."},
{m:"m1", g:"Bildraum", f:"Was ist der Bildraum und wie entsteht er?", b:"Bildraum entsteht durch die Gliederung des Formats in räumliche Bezüge (Vorder-, Mittel-, Hintergrund) und durch Mittel der Körper- und Raumdarstellung auf der Bildfläche. Frage: räumlich (Tiefenillusion) oder flächig?"},
{m:"m1", g:"Raumschaffende Mittel", f:"Nenne die einfachen Mittel der Raumdarstellung.", b:"Höhenunterschied, Größenabnahme, Überdeckung, Staffelung und Helligkeitsunterschied – einzeln oder kombiniert. Sie erzeugen Raumtiefe ohne konstruierte Perspektive."},
{m:"m1", g:"Parallelprojektion", f:"Was ist eine Parallelprojektion?", b:"Konstruierte Raumdarstellung, bei der real parallele Linien auch in der Darstellung parallel bleiben. Sie entspricht NICHT unserem Sehsinn (Bsp.: Isometrie, Dimetrie, Kavalier- und Militärperspektive)."},
{m:"m1", g:"Fluchtpunktperspektive", f:"Wie funktioniert die Fluchtpunktperspektive und welche zwei Formen gibt es?", b:"Konstruktives System aus Fluchtpunkt, Horizont und Fluchtlinien – kommt der menschlichen Wahrnehmung am nächsten. Zentralperspektive = Einfluchtpunktperspektive · Übereckperspektive = Zweifluchtpunktperspektive."},
{m:"m1", g:"Betrachterstandpunkt", f:"Welche Betrachterstandpunkte gibt es und wie wirken sie?", b:"Vogelperspektive (Aufsicht) = das Dargestellte wirkt schwach, klein, hilflos · Normalperspektive (Augenhöhe) = gleichberechtigt, neutral, einbindend · Froschperspektive (Untersicht) = mächtig, groß, erhaben."},
{m:"m1", g:"Luftperspektive", f:"Was ist die Luftperspektive und was bedeutet „Sfumato“?", b:"Bei zunehmender Entfernung werden Objekte undeutlicher, unschärfer, heller und kontrastärmer. Leonardo da Vinci nannte diese dunstig-verschwimmende Gestaltung „Sfumato“ (ital. = weich, rauchig)."},
{m:"m1", g:"Farbperspektive", f:"Wie funktioniert die Farbperspektive?", b:"Farben „verblauen“ mit zunehmender Entfernung (Verblauung). Warme Farben werden als nah, kalte Farben als weit entfernt empfunden – malerisches Raummittel der Landschaftsmalerei."},
{m:"m1", g:"Polyvalente Perspektive", f:"Was sind mehrdeutige Raumdarstellungen?", b:"Spiel mit unserer Raumerfahrung: polyvalente Perspektive (mehrere Blickpunkte gleichzeitig, kubistische Facetten → Allansichtigkeit), Zerrperspektive, Bedeutungsperspektive; mehrdeutige Räume z. B. im Surrealismus."},
{m:"m1", g:"Plastizität", f:"Welche Schattenarten erzeugen Plastizität?", b:"Körperschatten/Eigenschatten auf dem Objekt selbst – mit Halbschatten (abnehmende Helligkeit) und Kernschatten (dunkelste Stelle) – sowie der Schlagschatten/Außenschatten, den der Gegenstand auf seine Umgebung wirft."},
{m:"m1", g:"Farbmodulation", f:"Was ist Farbmodulation?", b:"Körperlichkeit, die nicht über Helligkeitsabstufungen von Hell nach Dunkel, sondern über die Variation eines Farbtones erzeugt wird – Plastizität allein durch Farbe."},
{m:"m1", f:"Welche Fragen stellt man im Analysebereich LICHT?", b:"Woher kommt das Licht – eindeutige Lichtquelle oder unbestimmtes, diffuses Streulicht? Wirft das Licht Schlagschatten? Welche Auswirkungen hat die Beleuchtung auf Dynamik, Spannung und Hervorhebung?"},
{m:"m1", f:"Welche zwei Grundtypen von Körperformen unterscheidet man?", b:"Geometrisch-konstruierte Körper (Kugel, Kubus, Quader, Pyramide, Zylinder, Kegel) und organische Körper (menschliche Körper, Pflanzen, Tiere)."},
{m:"m1", f:"Wie prüft man im Analysebereich KÖRPER/RAUM/LICHT die Räumlichkeit?", b:"Räumlich oder flächig? → Aufteilung in Vorder-/Mittel-/Hintergrund · einfache raumschaffende Mittel · perspektivisch oder aperspektivisch · konstruiert (Parallel-/Fluchtpunkt) vs. malerisch (Farb-/Luftperspektive) vs. mehrdeutig · Betrachterstandpunkt · Plastizität durch Schatten."},
{m:"m1", g:"Bildformat", f:"Welche Bildformate nennt man in der Analyse?", b:"Hochformat, Querformat, Rondo (Rundbild), Quadrat, Parallelogramm u. a. – das Format prägt das Sichtfeld: Querformat betont ein natürliches, weites Sichtfeld."},
{m:"m1", f:"Was versteht man unter Bewegungstendenz?", b:"In gegenständlichen Bildern entstehen Bewegungen durch sich bewegende Figuren, Blickrichtungen oder Diagonalen, die das Betrachterauge weiterführen. Sie machen eine Komposition dynamisch."},

/* ===== Modul 2: Farbwissen ===== */
{m:"m2", f:"Was ist der Unterschied zwischen „Farbe“ und „Farbmittel“?", b:"Farbe = der Farbeindruck, der entsteht, wenn Licht auf Oberflächen trifft und vom Auge als Sinnesempfindung wahrgenommen wird. Farbmittel = das materielle Pigment bzw. der Farbstoff."},
{m:"m2", g:"Farbdimensionen", f:"Welche drei Dimensionen hat eine (Pigment-)Farbe?", b:"1. Farbton (Farbrichtung, z. B. Blau) · 2. Helligkeit (Tonwert, Eigenhelle) · 3. Intensität (Reinheit/Sättigung)."},
{m:"m2", g:"Farbe-an-sich-Kontrast", f:"Itten 1/7: Farbe-an-sich-Kontrast", b:"Die Gegenüberstellung reinbunter, gesättigter Farben. Wirkung: leuchtend, kraftvoll – z. B. intensive Primärfarben bei Stoffen."},
{m:"m2", g:"Hell-Dunkel-Kontrast", f:"Itten 2/7: Hell-Dunkel-Kontrast", b:"Unterschiede in den Tonwerten/Helligkeitswerten. Wirkt hervorhebend und spannungsvoll – helle Objekte vor dunklem Grund springen ins Auge."},
{m:"m2", g:"Kalt-Warm-Kontrast", f:"Itten 3/7: Kalt-Warm-Kontrast – mit Temperaturbereichen", b:"Warm = Gelb bis Rotviolett · Kalt = Gelbgrün bis Violett. Die Gegenüberstellung erzeugt Spannung und Lebendigkeit (z. B. rotes Kleid neben blauem Stoff)."},
{m:"m2", g:"Komplementärkontrast", f:"Itten 4/7: Komplementärkontrast", b:"Zwei im Farbkreis gegenüberliegende Farben (z. B. Grün–Rot, Violett–Gelb, Orange–Blau) werden nebeneinander gestellt – maximale Spannung und Steigerung der Leuchtkraft."},
{m:"m2", g:"Simultankontrast", f:"Itten 5/7: Simultankontrast", b:"Eine Wechselwirkung bzw. optische Täuschung: Das Auge bildet zu einer gesehenen Farbe automatisch die Komplementärfarbe – benachbarte Flächen färben sich gegenseitig um."},
{m:"m2", g:"Qualitätskontrast", f:"Itten 6/7: Qualitäts- bzw. Intensitätskontrast", b:"Gegenüberstellung von reinbunten, gesättigten und getrübten/entsättigten Farben. Wirkt hervorhebend – im Hintergrund trüb, im Vordergrund satt (auch Mittel der Luftperspektive)."},
{m:"m2", g:"Quantitätskontrast", f:"Itten 7/7: Quantitäts- bzw. Mengenkontrast", b:"Gegenüberstellung unterschiedlich großer Farbflächen. Harmonisch ist das Verhältnis, wenn keine Farbe dominiert."},
{m:"m2", g:"Symbolfarbe", f:"Was ist eine Symbolfarbe?", b:"Eine Farbe mit festgeschriebener symbolischer Bedeutung. Höchster Symbolrang = höchster Materialwert: Die göttliche Sphäre wird z. B. in Gold dargestellt."},
{m:"m2", g:"Lokalfarbe", f:"Was ist Gegenstands- bzw. Lokalfarbe?", b:"Die charakteristische Eigenfarbe eines Gegenstandes (Rasen grün, Himmel blau). Wirkung: naturgetreu, natürlich, sachlich."},
{m:"m2", g:"Erscheinungsfarbe", f:"Was ist Erscheinungsfarbe?", b:"Der Gegenstand wird so gemalt, wie er sich unter bestimmten momentanen Lichtverhältnissen zeigt – nicht wie er „eigentlich“ ist. Wirkung: atmosphärisch, stimmungsvoll. (Zentral im Impressionismus.)"},
{m:"m2", g:"Ausdrucksfarbe", f:"Was ist Ausdrucksfarbe?", b:"Eine vom Gegenstand losgelöste Farbe, die Träger innerer Zustände ist – die Farbe drückt aus, statt abzubilden (wichtig z. B. im Expressionismus)."},
{m:"m2", g:"Autonome Farbe", f:"Was bedeutet autonome bzw. absolute Farbe?", b:"Die Farbe ist selbst das Thema des Bildes – ohne Gegenstandsbezug, z. B. in der abstrakten Malerei."},
{m:"m2", f:"Was unterscheidet Eigenwert und Darstellungswert der Farbe?", b:"Eigenwert = Farbe unabhängig vom Farbträger/Gegenstand (z. B. Expressionismus). Darstellungswert = Farbe abhängig vom Farbträger, dient der Abbildung (z. B. Realismus)."},
{m:"m2", g:"Kolorismus", f:"Was ist ein farbwertbestimmtes Malkonzept (Kolorismus)?", b:"Die Buntheit und Eigenwertigkeit der Farbe selbst ist das Gestaltungskonzept des Bildes."},
{m:"m2", g:"Valeurismus", f:"Was ist ein tonwertiges Malkonzept (Valeurismus)?", b:"Ton-in-Ton-Malerei mit feinen Helligkeitsunterschieden (Valeurs) innerhalb eines eingeschränkten Farbspektrums. Wirkung: ruhig, zurückhaltend, sachlich."},
{m:"m2", g:"Monochromie", f:"Was bedeutet monochromes Malkonzept?", b:"Malerei in den Tonwerten nur EINER Farbe (z. B. verschiedene Blaugrautöne)."},
{m:"m2", g:"Lasurtechnik", f:"Was ist die Lasurtechnik?", b:"Die Farbe wird in mehreren dünnen, lasierenden (halb-)durchsichtigen Schichten übereinander aufgetragen – ohne sichtbaren Pinselduktus; wirkt ruhig und naturgetreu."},
{m:"m2", g:"Primamalerei", f:"Was ist Primamalerei?", b:"Die Farbe wird in einer Schicht aufgetragen – meist deckend und ggf. pastos (dicklich). Auch „alla prima“: in einem Arbeitsgang, ohne Untermalung."},
{m:"m2", g:"Pinselduktus", f:"Was prüft man bei Farbauftrag und Pinselduktus?", b:"Ist der Pinselstrich sichtbar (Duktus) oder verschwindet er? Auftragsarten: getupft, flächig, gespachtelt; Konsistenz: lasierend, deckend, pastos, alla prima."},
{m:"m2", f:"Psychologische vs. symbolische Farbwirkung – je ein Beispiel?", b:"Psychologisch: Rot wirkt aggressiv (unmittelbare Empfindung). Symbolisch: Rot steht für Liebe (kulturell festgelegte Bedeutung)."},
{m:"m2", g:"Was-und-Wie-Probe", f:"Grundregel der Groß-/Kleinschreibung von Farbnamen (Was-und-Wie-Probe)", b:"Mit „Was?“ erfragt → Nomen → groß: „Was zeigt die Ampel? Rot.“ Mit „Wie?“ erfragt → Adjektiv → klein: „Die Ampel ist rot.“ Ist beides möglich, sind beide Schreibweisen korrekt (orange / Orange)."},
{m:"m2", f:"Wie schreibt man Farben nach einer Präposition?", b:"Immer groß – die Präposition bezieht sich auf ein Nomen: „ein Traum in Orange“, „Er geht bei Rot über die Ampel.“"},
{m:"m2", f:"Woran erkennt man die Großschreibung einer Farbe als Nomen?", b:"Am Artikel (bestimmt oder unbestimmt): „ein helles Orange“, „das helle Orange“. Faustregel: mit Artikel groß."},
{m:"m2", f:"Farbtonungen wie „tiefgrün“, „himmelblau“, „knallrot“ – zusammen oder mit Bindestrich?", b:"Zusammen und ohne Bindestrich: Das erste Adjektiv bestimmt nur den Farbton näher – es bleibt dieselbe Farbe. Der See ist tiefgrün, die Kirschen sind knallrot."},
{m:"m2", g:"Bindestrich bei Farben", f:"„blau-rot gestreift“ vs. „blau-rot“ vs. „blaurot“ – was gilt?", b:"Zwei erkennbare Einzelfarben → Bindestrich: „blau-rot gestreift“, „Das T-Shirt ist blau-rot.“ Eine Mischung aus beiden Farben → ein Wort: „blaurot“."},
{m:"m2", f:"„schwarzmalen“, „blaumachen“, „rotsehen“ – und die Ausnahme?", b:"Bei neuer (übertragener) Bedeutung schreibt man zusammen: schwarzmalen = negativ darstellen, blaumachen = ohne Grund fehlen, rotsehen = wütend werden. AUSNAHME: Mit „zu“ wird getrennt („zu schwarz malen“); bleibt die wörtliche Bedeutung erhalten, ebenfalls getrennt („den Rand schwarz malen“)."},
{m:"m2", f:"Wie empfiehlt der Duden „orange Hose“ besser zu schreiben – und warum?", b:"„orange Hose“ ist möglich, klingt aber seltsam. Besser: Adjektiv mit -farben/-farbig: „orangefarbene Hose“. Das gilt auch für rosa → rosafarben, türkis → türkisfarben/türkisfarbig, lila → lilafarben."},
{m:"m2", f:"Farbnamen in Eigennamen – Groß- oder Kleinschreibung?", b:"Eindeutige Eigennamen (einzigartig) schreibt man groß: das Schwarze Meer, der Weiße Sonntag, die Grüne Insel. Beim „Blauen Planeten“ erlaubt der Duden auch Kleinschreibung, empfiehlt aber groß. Bei nicht einzigartigen Begriffen ist meist beides erlaubt: die rote/Rote Karte, der blaue/Blaue Brief."},

/* ===== Modul 3: Bildanalyse-Methodik ===== */
{m:"m3", g:"Bildanalyse-Schema", f:"Nenne die großen Schritte der Analyse von Gemälden und Grafiken.", b:"(Rahmendaten/Einleitungssatz mit Bildmotiv) → 1. BESCHREIBUNG (Erster Eindruck + sachliche Beschreibung) → 2. ANALYSE (bildnerische Mittel + ihre Wirkung) → 3. INTERPRETATION/DEUTUNG."},
{m:"m3", g:"Rahmendaten", f:"Welche Rahmendaten gehören in den Einleitungssatz?", b:"Titel, Künstler, Entstehungsjahr, Aufbewahrungsort, Bildmaße und Format (Hoch-, Querformat, Rondo, Quadrat), Technik (Gemälde, Zeichnung, Druck …), Bildgenre (Bildnis, Landschaft, Stillleben …) – und das Bildmotiv (Thema der Darstellung)."},
{m:"m3", g:"Bildgenre", f:"Was ist ein Bildgenre?", b:"Die Motiv- bzw. Inhaltsgattung eines Werkes: z. B. Bildnis/Porträt, Landschaft, Stillleben, Genre-/Historienbild, Akt."},
{m:"m3", g:"Beschreibung", f:"Welchen Regeln folgt die sachliche Beschreibung?", b:"Was ist zu sehen? – ohne wertende Äußerungen. Vom Wesentlichen zum Detail. Bildraum UND dargestellten Raum berücksichtigen: Figuren (Kleidung, Attribute, Ausdruck), Handlung, Gegenstände, räumlicher Zusammenhang, Landschaft; gegliedert nach Vorder-, Mittel-, Hintergrund."},
{m:"m3", g:"Erster Eindruck", f:"Wohin gehört der Erste Eindruck und wie formuliert man ihn?", b:"An den Anfang der Beschreibung: Wie wirkt das Werk? (einladend, irritierend, traurig, kalt …). Formuliert als Wirkung/Assoziation („Das Bild wirkt … / Ich assoziiere …“), noch ohne Begründung über die Bildmittel."},
{m:"m3", g:"Analyse", f:"Was ist die Kernregel jeder Bildanalyse?", b:"Jedes bildnerische Mittel wird auf seine WIRKUNG bezogen: Welches gestalterische Mittel erzeugt welche Wirkung beim Betrachter? Beschreibung allein reicht nie – immer „Mittel → Wirkung“. (UA = unter Anwendung der Mittel.)"},
{m:"m3", g:"Bildanalyse-Schema", f:"Welche Sinnabschnitte hat der Analyse-Teil des Schemas?", b:"FARBE · BILDMOTIV · KOMPOSITION/BILDAUFBAU · PUNKT, LINIE, FLÄCHE · KÖRPER/RAUM/LICHT – die relevanten Gesichtspunkte werden gegliedert, jeder mit Wirkungszusammenhang."},
{m:"m3", g:"Bildmotiv", f:"Was analysiert man am Bildmotiv?", b:"Auswahl und Arrangement der Bildgegenstände: Hauptmotiv(e), welche Bildelemente sind für die Aussage wichtig, welche Assoziationen/Stimmungen löst die Motivwahl aus – bei Figuren auch Haltung, Gestik, Mimik, Bewegung, Alter, Kleidung, Accessoires."},
{m:"m3", g:"Interpretation", f:"Was passiert im Schritt Interpretation/Deutung?", b:"Die erarbeiteten Fakten werden zu einer inhaltlichen Einheit verbunden: Bestätigt die Analyse den Ersten Eindruck? Wie hoch ist der Ikonizitätsgrad? Einbezug von Hintergrundwissen – Quellen, Zitate, Symbolik, Kunst-/Kulturgeschichte."},
{m:"m3", g:"Ikonizitätsgrad", f:"Was ist der Ikonizitätsgrad?", b:"Der Grad der Naturtreue eines Bildes. Drei Illusionen: Stofflichkeit, Körperlichkeit, Räumlichkeit. Drei Richtigkeiten: anatomische, farbige und zeichnerische Richtigkeit."},
{m:"m3", g:"Ikonografie", f:"Aus welchen vier Perspektiven deutet man ein Werk hintergrundbezogen?", b:"Zeitgeschichtlich (welche Epoche/Umwelt?), biografisch (Künstler), stilgeschichtlich (Stilrichtung/Epochenmerkmale) und ikonografisch (Motiv-/Symboltradition)."},
{m:"m3", g:"Formulierungshilfe", f:"Formulierungshilfen für den Ersten Eindruck (2 Beispiele)?", b:"„Auf mich wirkt das Bild mit einer beunruhigenden Ruhe und Stille.“ · „Trotz der hellen Farben wirkt das Bild auf mich düster und beängstigend.“ – immer: Wirkung + Begründung."},
{m:"m3", g:"Formulierungshilfe", f:"Muster für einen Einleitungssatz (Malerei)?", b:"„Francisco de Goya hat das Werk „Der Sonnenschirm“ im Jahre 1777 mit Öl auf Leinwand gemalt. Es hat die Maße 104 × 152 cm und hängt heute im Museo del Prado, Madrid. Zu sehen ist ein Paar unter einem Sonnenschirm.“"},
{m:"m3", g:"Formulierungshilfe", f:"Formulierungshilfen zur Beschreibung (3 Phrasen)?", b:"„Im Mittelgrund ist … zu sehen.“ · „Im Mittelpunkt / optischen Zentrum des Bildes steht …“ · „Die Person ist im Anschnitt dargestellt.“ / „Das Bild lässt sich in Vorder-, Mittel- und Hintergrund aufteilen.“"},
{m:"m3", g:"Formulierungshilfe", f:"Formulierungshilfen zur FARBE (2 Beispiele)?", b:"„Der grüne Sonnenschirm und die roten Blumen bilden einen Komplementärkontrast.“ · „Durch das helle Tuch und den dunklen Hintergrund entsteht ein ausgeprägter Hell-Dunkel-Kontrast – das Tuch wird in den Vordergrund gerückt.“"},
{m:"m3", g:"Formulierungshilfe", f:"Formulierungshilfen zu PERSPEKTIVE/RAUM (2 Beispiele)?", b:"„Die Raumillusion wird geschaffen durch … / … verleiht dem Bild Tiefe.“ · „Der Betrachter schaut in leichter Untersicht auf die Figur – sie wirkt erhaben und majestätisch.“"},
{m:"m3", g:"Formulierungshilfe", f:"Formulierungshilfen zur KOMPOSITION (2 Beispiele)?", b:"„Die Symmetrie wird durch eine diagonale Bildachse gebrochen und verleiht dem Bild Spannung.“ · „Der Blick des Betrachters wird durch … auf … gelenkt.“"},
{m:"m3", g:"Formulierungshilfe", f:"Formulierungshilfen zur INTERPRETATION (3 Beispiele)?", b:"„Der Künstler verwendet …, um … auszudrücken.“ · „… symboliert … / … ist typisch für …“ · „Bei genauerer Betrachtung ist die Darstellung widersprüchlich: Trotz … wirkt …“"},
{m:"m3", g:"Œuvre", f:"Was bedeutet „Œuvre“ – und wie gebraucht man den Begriff korrekt?", b:"Das GESAMTwerk eines Künstlers (nicht ein einzelnes Bild!). Richtig: „Das Thema … zieht sich wie ein roter Faden durch das Œuvre der Künstlerin.“"},
{m:"m3", f:"Warum dürfen Beschreibung und Bewertung/Deutung nicht vermischt werden?", b:"Weil die Analyse objektiv die gestaltenden Mittel und ihre Wirkung erarbeiten muss; die Deutung baut erst DANACH auf diesen Fakten auf. Eine vermischte Beschreibung kann die Wirkung nicht mehr begründen."},
{m:"m3", f:"Wie prüft man bei der Analyse, ob ein Mittel wirklich relevant ist?", b:"Man gliedert die Gesichtspunkte in Sinnabschnitte und bezieht jedes Mittel auf die Bildwirkung: Hat das Mittel nachweisbaren Einfluss auf Eindruck/Aussage, ist es analysierenswert – sonst lässt man es weg."},

/* ===== Modul 4: Impressionismus ===== */
{m:"m4", f:"Wann ist die Epoche des Impressionismus?", b:"Ca. 1860 – 1905."},
{m:"m4", g:"Impressionismus", f:"Was bedeutet „Impressionismus“ wörtlich?", b:"Vom frz. impression = „Eindruck“. Impression meint die subjektive Wahrnehmung der Welt, BEVOR die rationale Verarbeitung der Sinneseindrücke einsetzt."},
{m:"m4", g:"Namensgebung", f:"Wie erhielt der Impressionismus seinen Namen?", b:"Nach Claude Monets Bild „Impression, soleil levant“ („Eindruck bei Sonnenaufgang“, 1872). Der Kritiker Louis Leroy griff den Titel 1874 in einer vernichtenden Rezension der Gruppenausstellung auf und machte ihn zum Gruppen-/Stilbegriff – ursprünglich spöttisch gemeint („Eine Tapete im Urzustand ist ausgearbeiteter als dieses Seestück.“)."},
{m:"m4", g:"Société anonyme", f:"Was geschah 1874 in Paris?", b:"Rund 30 unabhängige Künstlerinnen und Künstler organisierten selbst eine Ausstellung – im Atelier des Fotografen Nadar –, weil sie vom Salon abgelehnt wurden. Ihre Initiative nannten sie „Société anonyme des artistes peintres, sculpteurs, graveurs“. Dort prägte Leroy den Begriff."},
{m:"m4", f:"Warum setzte sich der abgeleitete Begriff trotzdem durch?", b:"Weil die Künstler selbst keinen Namen prägten – und weil „impression“ im ästhetischen Diskurs schon eingeführt war: Er beschrieb die subjektive Wahrnehmung vor rationaler Verarbeitung."},
{m:"m4", g:"pochade / étude", f:"Was unterschieden „impression“/„pochade“ von „étude“ im 19. Jh.?", b:"impression/pochade = flüchtige, schnelle Skizze, die einem ersten unmittelbaren Eindruck folgt · étude = langsamere, genaue Wiedergabe des Motivs. Monet erhob die Skizze zum Kunstwerk, indem er sie ausstellte."},
{m:"m4", f:"Warum ist die „Spontaneität“ impressionistischer Bilder eine Täuschung?", b:"Kritiker wie Frédéric Chevalier (1877) durchschauten den „Anschein der Spontaneität“: Die scheinbar zufälligen Blickwinkel und der skizzenhafte Look waren bewusst konstruiert („rohe Kunstfertigkeit“, „bewusst evozierte Zusammenhanglosigkeit“)."},
{m:"m4", g:"Impressionismus", f:"Was ist Impressionismus in einem Satz?", b:"Eine Stilrichtung der Malerei mit heller Palette, lockerem, skizzenhaftem Farbauftrag mit sichtbaren Pinselstrichen, Malen vor dem Motiv und meist Pleinairmalerei – ohne Geschichtenerzählen, fokussiert auf sinnliche Wahrnehmung."},
{m:"m4", g:"Pleinairmalerei", f:"Was ist Pleinair- bzw. Freilichtmalerei – und warum war sie zentral?", b:"Malen im Freien (frz. en plein air) direkt vor dem Motiv. Spontane Interaktion mit der Natur und zügige Umsetzung galten als Grundbedingungen einer authentischen modernen Landschaftsmalerei – wegen flüchtiger Lichtstimmungen arbeitete man auch in Serien."},
{m:"m4", g:"Palettenaufhellung", f:"Was bedeutet „Aufhellung der Palette“?", b:"Möglichst reine, helle Farben; Vermeidung von Schwarz und Abwendung von der traditionellen Hell-Dunkel-Malerei (chiaroscuro). Elfenbeinschwarz, Preußischblau und Bitumenfarben verschwanden weitgehend; dafür Chromgelb, Orange-/Rosatöne, Grün, Ultramarin und mehr Bleiweiß zum Aufhellen."},
{m:"m4", g:"Alla-prima-Malerei", f:"Was passiert bei der Alla-prima-Malerei mit dem Komma-Pinselstrich (virgulisme)?", b:"Ohne Vorzeichnung wird direkt auf die Leinwand gemalt – mit lockeren, kurzen, kommaartigen Pinselstrichen (frz. virgulisme), die sich erst aus einiger Entfernung im Auge des Betrachters vermischen → intensivere, vibrierende Farbigkeit."},
{m:"m4", g:"Pinselduktus", f:"Welche Rolle spielen Pinselduktus und Farbauftrag?", b:"Der Pinselduktus bleibt sichtbar, teilweise wird pastos (dick) aufgetragen – das Bildsurface wird zur lebendigen, vibrierenden Maloberfläche."},
{m:"m4", f:"Was heißt „Zerlegen der Farben nach dem prismatischen Spektrum“?", b:"Die Farben werden entsprechend den Gesetzen des prismatischen Spektrums in ihre Spektralfarben zerlegt und nebeneinandergesetzt statt gemischt – das Licht selbst wird zum Baustoff des Bildes."},
{m:"m4", g:"Momentanheit", f:"Was wollen die Impressionisten festhalten?", b:"Den unmittelbaren (Seh-)Eindruck, den Momentanen, flüchtigen Augenblick – inkl. Atmosphäre und Erscheinung der Dinge (Erscheinungsfarbe). Dafür verzichten sie auf Detailtreue und Naturalismus; der optische Eindruck wird „ungefiltert durch Reflexion“ wiedergegeben."},
{m:"m4", g:"Anschnitt", f:"Was bedeutet die „Betonung des Ausschnitthaften“?", b:"Die Komposition betont das Zufällige: angeschnittene Figuren, Bildränder, die mitten durch Motive schneiden – wie ein Schnappschuss. Der Eindruck entsteht im Augenblick des Hinsehens."},
{m:"m4", f:"Wie erzeugt der Impressionismus Raumtiefe – und wie nicht?", b:"NICHT durch lineare Perspektive nach geometrischen Regeln, sondern malerisch – durch Farbe, Licht und Atmosphäre (Erscheinungsfarbe, Luftperspektive)."},
{m:"m4", g:"Offene Form", f:"Was ist die „offene Form“ im Impressionismus?", b:"Die Auflösung scharfer Konturen und fester Formen zugunsten der Farbe. Die offene Form motiviert den Betrachter zu eigenen Sehleistungen, Empfindungen und Mitarbeit an der Bildgestalt."},
{m:"m4", g:"impressionistische Plastik", f:"Wie verändert der Impressionismus die Bildhauerei?", b:"Skulpturen erhalten eine malerische, skizzenhafte Gestalt, bezogen auf Licht, Oberflächen und Bewegung der Figur. Durch „Buckel und Höhlungen“ entsteht eine bewegte, fließende Oberfläche – neue Lebendigkeit und Natürlichkeit der Plastik."},
{m:"m4", f:"Welche Themen malt der Impressionismus?", b:"Fluss- und Kulturlandschaften mit Wasserreflexen · die Metropole Paris (Haussmannisierung) · Freizeitvergnügungen (Ausflugslokale, Picknick, Pferderennbahn, Oper, Tänzerinnen) · Tages-/Jahreszeitliche Lichtstimmungen · scheinbar belanglose Momente (Morgentoilette, Schuhe schnüren)."},
{m:"m4", g:"Gegenwartsbezug", f:"Was lehnen die Impressionisten thematisch ab?", b:"Historische, literarische und religiöse Sujets sowie politische/soziale Aussagen. Sie bejahen stattdessen das moderne (Großstadt-)Leben – Gegenbewegung zur Salonmalerei und zum Akademismus (Baudelaires Forderung nach dem „modernen Leben“)."},
{m:"m4", g:"Haussmannisierung", f:"Was bezeichnet „Haussmannisierung“?", b:"Die Modernisierung und Umgestaltung von Paris unter Napoleon III. (Boulevards, Rasterstraßen) – die neue Großstadt wurde zum Topos des Impressionismus (z. B. Caillebotte, Monet, Renoir)."},
{m:"m4", g:"Riviere-Zitat", f:"Zitiere und erkläre das Riviere-Zitat.", b:"„Einen Gegenstand um der Farben willen zu malen und nicht um seiner selbst willen, das ist es, was den Impressionisten von den anderen Malern unterscheidet.“ (Georges Riviere) → Das Interesse verschiebt sich vom Motiv auf die malerische Behandlung des Motivs."},
{m:"m4", g:"Serienmalerei", f:"Warum malte Monet in Serien?", b:"Weil das eigentliche Bildthema die flüchtige Lichtstimmung ist: Dasselbe Motiv wird in verschiedenen Tages-/Jahreszeiten-Lichtern festgehalten (Oberfläche und äußere Erscheinung der alltäglichen Umgebung)."},
{m:"m4", g:"Technische Voraussetzungen", f:"Welche technischen Voraussetzungen ermöglichten den Impressionismus?", b:"Synthetische (industriell hergestellte) Farben in Zinntuben, transportable Staffeleien, vorgrundierte Leinwände auf Keilrahmen – und Sonnenschirme, die sowohl die Maler schützten als auch das Eigenlicht der Farben wahrten."},
{m:"m4", f:"Welche neuen Farben kamen auf die impressionistische Palette?", b:"Chromgelb (erfunden 1809), Orange- und Rosatöne, Grün, Ultramarin – dazu mehr Bleiweiß zum Aufhellen. Elfenbeinschwarz, Preußischblau und Bitumenfarben wurden selten."},
{m:"m4", f:"Warum malten die Malerinnen des Impressionismus v. a. die häusliche Welt?", b:"Als Frauen der gehobenen Gesellschaft galt es als verpönt, sich in Cafés zu treffen. Deshalb behandelten sie v. a. die weibliche und häusliche Welt: Mutterschaft und Porträts von Familienmitgliedern (z. B. Berthe Morisot)."},
{m:"m4", g:"Degas", f:"Welche Sonderrolle nahm Edgar Degas ein?", b:"Er führte die Figurenmaler, die sich stärker in der Tradition der Akademie sahen, und lehnte die Bezeichnung „Impressionismus“ für seine Werke ab."},
{m:"m4", f:"Nenne die Hauptvertreter des Impressionismus in der MALEREI (mit Lebensdaten).", b:"Camille Pissarro (1830–1903) · Édouard Manet (1832–1883) · Berthe Morisot (1844–1926) · Edgar Degas (1834–1917) · Claude Monet (1840–1926) · Auguste Renoir (1841–1919) · Max Liebermann (1847–1935) · Lovis Corinth (1858–1925)."},
{m:"m4", f:"Nenne die Hauptvertreter des Impressionismus in der PLASTIK.", b:"Auguste Rodin (1840–1917) · Camille Claudel (1864–1943) · Edgar Degas · Medardo Rosso (1858–1928)."},
{m:"m4", f:"Welche Bedeutung hat Monets „Impression, soleil levant“?", b:"Das Bild von 1872 gab der ganzen Epoche ihren Namen (nach Leroys Kritik 1874). Es zeigt: Die Skizze wurde zum Kunstwerk erhoben – ein Experiment, Seheindruck vor Vollendung zu stellen."},

/* ===== Modul 5: Caillebotte ===== */
{m:"m5", g:"Caillebotte Rahmendaten", f:"Nenne die Rahmendaten von Caillebottes „Straße in Paris an einem regnerischen Tag“.", b:"Gustave Caillebotte, 1877, Öl auf Leinwand, 212,2 × 276 cm, Querformat, heute Art Institute of Chicago. Motiv: eine Straßenkreuzung mehrerer Boulevards an einem Regentag, auf der vereinzelte Menschengruppen mit Regenschirmen unterwegs sind."},
{m:"m5", f:"Wie ist der Einleitungssatz dieser Analyse aufgebaut?", b:"„Das Gemälde „Straße in Paris an einem regnerischen Tag“ wurde von Gustave Caillebotte 1877 mit Ölfarben auf Leinwand gemalt und zeigt eine Straßenkreuzung mehrerer Boulevards an einem Regentag, auf der vereinzelte Gruppen von Menschen mit Regenschirmen unterwegs sind.“ – Titel + Künstler + Jahr + Technik + Motiv in einem Satz."},
{m:"m5", g:"Doppelte Bildwirkung", f:"Welche ZWEI gegensätzliche Bildwirkungen werden dem Bild zugeschrieben?", b:"Einerseits: trist, bedrückend, kühl, ungemütlich, einsam, monoton, still, statisch, sachlich, leer, isoliert. Andererseits: dynamisch, lebendig, bewegt, elegant, beschäftigt, natürlich, alltäglich."},
{m:"m5", f:"Beschreibe das Hauptfiguren-Paar im Vordergrund.", b:"Rechts der Bildmitte läuft ein elegant gekleidetes Paar dicht unter EINEM Regenschirm auf den Betrachter zu; beide Köpfe nach links gedreht; es ist knieabwärts vom unteren Bildrand angeschnitten. Die Frau (rechts) trägt auberginefarbene Jacke mit Pelzsaum und passenden Rock, dunkelbraune Fellmütze, Perlenohrring, rot geschminkte Lippen, entspannte Züge. Der Mann (links) trägt knielangen petrol-/braunfarbenen Mantel, steingraue Hose, schwarze Fliege, schwarzen Zylinder, schmalen Oberlippenbart, rechte Hand in der Manteltasche, angewinkelter Arm hält den Schirm, bei dem die Frau eingehakt ist."},
{m:"m5", f:"Welche weitere Figur belebt den rechten Bildrand – und wie ist sie dargestellt?", b:"Ein weiterer männlicher Fußgänger mit Regenschirm und Zylinder in Rückenansicht, der zur Hälfte vom rechten Bildrand angeschnitten ist und sich auf das Paar zubewegt."},
{m:"m5", f:"Welche Wirkungen gehen von den MOTIVEN des Bildes aus?", b:"Vornehm gekleidete Passanten → bürgerlich, elegant, alltäglich/sonntäglich · nasses Kopfsteinpflaster → ungemütlich, kühl, trist · Regenschirme → beschützend, gemütlich · Straßenlaternen und ähnliche Fassadenfluchten → urban, eintönig, anonym · einzelne schreitende Passanten → isoliert und anonym, aber auch alltäglich, beschäftigt, belebt."},
{m:"m5", g:"Komposition", f:"Fasse die Kompositionsanalyse des Bildes zusammen.", b:"Querformat (natürliches Sichtfeld) · senkrechte Linien (statisch, standhaft) · Laterne auf der Mittelachse (hervorhebend, bildteilend, ausgewogen) · schiefe Fluchtlinien (dynamisch, blickführend, raumtiefeerzeugend) · waagerechter Horizont (ruhig, weit, Standpunkt betonend) · gebogene Linien der Schirme (bewegt, beschützend) · Figurenballung rechts (eng, gedrängt) · Dreiecksform der Hintergrundgebäude · Achsen der Vorder-/Mittelfiguren im goldenen Schnitt (harmonisch) · angeschnittene Elemente wie Kutsche und rechter Mann (spontan, zufällig, flüchtig)."},
{m:"m5", g:"Bildraum", f:"Mit welchen Mitteln erzeugt Caillebotte Räumlichkeit?", b:"Fluchtpunktperspektive (Übereck- und Zentralperspektive: blickführend, weit/tief, konstruiert) · einfache raumschaffende Mittel (Überdeckung, Größenabnahme, Höhenunterschied) · Betrachterstandpunkt auf Augenhöhe der vorderen Figuren (einbindend, identifizierend, unmittelbar) · Plastizität durch Hell-Dunkel-Modellierung (z. B. Regenschirme: naturgetreu)."},
{m:"m5", f:"Fasse die Farbanalyse des Bildes zusammen.", b:"Helle Violettgrau- und Ockertöne (dezent, eintönig) + helles Gelb (Himmel) und Rotbraun (Fassaden) (warm, belebend) · Kalt-Warm- und Komplementärkontrast Violett–Gelb (spannungsvoll) · Hell-Dunkel-Kontraste Figuren/Hintergrund (hervorhebend) · Qualitätskontrast: sattes Grün/Rotbraun vorn vs. Grauviolett hinten (= Luftperspektive) · valeuristisches Malkonzept mit feinen Valeurs (ruhig, sachlich) · Lokalfarbe (naturgetreu) + Erscheinungsfarbe/Verblauung (atmosphärisch)."},
{m:"m5", g:"Pinselduktus", f:"Wie malt Caillebotte – und warum ist das für den Impressionismus UNtypisch?", b:"Lasierend UND deckend OHNE sichtbaren Pinselduktus, im Vordergrund detailliert und plastisch (fließende Farbverläufe), nur im Hintergrund skizzenhaft/schemenhaft. Diffuses Licht des Regentags (ruhig, still, einheitlich). Die Aufhellung der Palette durch helle Pastelltöne und Teile der Erscheinungsfarbe sind dagegen wieder typisch impressionistisch."},
{m:"m5", g:"Interpretation", f:"Ordne das Bild stilistisch ein und begründe.", b:"Dem Impressionismus zugehörig: alltägliche Szene des modernen Lebens statt Salonmotive; der Boulevard als Produkt der städtebaulichen Veränderungen durch Industrialisierung und Haussmannisierung; Wiedergabe von Atmosphäre, Witterung und momenthafter Stimmung; angeschnittene Figur/aus dem Bild fahrende Kutsche → Schnappschuss-Charakter (Flüchtigkeit); in Teilen weiche Konturen + Aufhellung der Palette."},
{m:"m5", g:"Fazit Caillebotte", f:"Formuliere das Fazit der Caillebotte-Analyse.", b:"Das Gemälde ist „noch“ einer naturalistischen, detailgenauen, abbildhaften Darstellung verpflichtet (fehlender skizzenhafter Charakter, traditioneller Farbauftrag), weist aber in Motiv, Komposition und Farbigkeit typisch impressionistische Merkmale auf – es steht zwischen Naturalismus und Impressionismus."},
{m:"m5", f:"Welche Situation stellt das Bild wahrscheinlich dar?", b:"Eine sonntägliche Regentagssituation: gut gekleidete Menschen des gehobenen Bürgertums flanieren durch die Straßen – teils eiligen Schritts, teils entspannt und geschützt durch Regenschirme."},
{m:"m5", f:"Wie wirkt die diffuse Lichtsituation im Bild?", b:"Als warm leuchtendes, diesiges Regenlicht: ruhig, still, einheitlich und eintönig – aber durch die hellen Pastelltöne auch atmosphärisch-stimmungsvoll (Erscheinungsfarbe)."},
{m:"m5", f:"Wodurch genau entsteht der „Schnappschuss“-Charakter des Bildes?", b:"Durch das Momenthafte der Komposition: die Bewegung der Figuren, der Bildausschnitt mit angeschnittener männlicher Figur rechts und die bereits halb aus dem Bild gefahrene Kutsche links. Das betont den flüchtigen, zufälligen Augenblick – ein typisches Mittel der Impressionisten."},
{m:"m5", g:"Luftperspektive", f:"Wo zeigt das Bild eine Luftperspektive bzw. einen Qualitätskontrast?", b:"Im Hintergrund: Das satte Grün und Rotbraun des Vordergrunds steht gegen das getrübte Grauviolett des Hintergrunds – die Farbqualität nimmt mit der Entfernung ab (Luftperspektive), was den Vordergrund hervorhebt und spannungsvoll wirkt."},
{m:"m5", g:"Valeurismus", f:"Warum heißt das Malkonzept des Bildes „valeuristisch“?", b:"Weil Caillebotte mit feinen Farbabstufungen und Tonwerten (Valeurs) innerhalb eines eingeschränkten Farbspektrums malt – das wirkt ruhig, zurückhaltend, einfach und sachlich."}
];

/* ---------- Glossar (Begriff → Erklärung, mit Modul-Querlinks) ---------- */
DATA.glossary = [
  {t:"Bildmittel", d:"Die gestaltenden Mittel eines Kunstwerks in vier Bereichen: Linien/Flächen, Farbe, Bildraum, Komposition. Inhalt (Warum) und Form (Wie) sind untrennbar verknüpft – Bildmittel erklären die Bildwirkung.", m:"m1", also:["m3","m5"]},
  {t:"Punkt", d:"Kleinste wahrgenommene Bildeinheit; als Reihung, Raster, Streuung oder Ballung gesetzt; viele Punkte ergeben Muster, Struktur oder Licht-Schatten-Modellierung.", m:"m1", also:["m3"]},
  {t:"Linie", d:"Kontur-/Umrisslinie, Binnenlinie, dekorative oder autonome Linie (ohne Gegenstandsbezug). Richtungen wirken: senkrecht = statisch, waagerecht = ruhig, schräg = dynamisch-blickführend, gebogen = bewegt.", m:"m1", also:["m3","m5"]},
  {t:"Fläche", d:"Durch Farben/Linien begrenzte Form: geometrisch, organisch oder frei. Ausgestaltung flächig, plastisch (Hell-Dunkel), fließend, ornamental oder stofflich.", m:"m1", also:["m3"]},
  {t:"Komposition", d:"Grundstruktur/Bildaufbau: Format, Richtungen, Kompositionsfiguren, Positionen, Ordnungsprinzipien, Proportionen. Statisch = ruhig; dynamisch = bewegt.", m:"m1", also:["m3","m5"]},
  {t:"Kompositionsfigur", d:"Geometrische Grundfigur des Aufbaus: Dreieck (göttliche Dreifaltigkeit; statisch-fest), Kreis/Halbkreis (Vollkommenheit des Himmels), Oval, Quadrat.", m:"m1", also:["m5"]},
  {t:"Kompositionsskizze", d:"Skizze der Kompositionslinien (auch fiktiv durch Blickrichtungen), um den Bildaufbau sichtbar zu machen.", m:"m1", also:["m3"]},
  {t:"Ordnungsprinzipien", d:"Reihung, Ballung, Streuung, Gruppierung, Rhythmus, Symmetrie/Asymmetrie, Orthogonalität.", m:"m1", also:["m5"]},
  {t:"Goldener Schnitt", d:"Proportionsverhältnis 1 : 1,618 bzw. ca. 3/8 zu 5/8; wirkt harmonisch und ausgewogen.", m:"m1", also:["m5"]},
  {t:"Bildraum", d:"Der auf der Fläche suggerierte Raum: Gliederung in Vorder-, Mittel-, Hintergrund plus Raummittel.", m:"m1", also:["m3","m5"]},
  {t:"Raumschaffende Mittel", d:"Einfache Mittel der Tiefenwirkung: Höhenunterschied, Größenabnahme, Überdeckung, Staffelung, Helligkeitsunterschied.", m:"m1", also:["m5"]},
  {t:"Parallelprojektion", d:"Konstruierte Raumdarstellung: parallele Linien bleiben parallel (Isometrie, Dimetrie, Militärperspektive) – nicht sehsinngetreu.", m:"m1", also:[]},
  {t:"Fluchtpunktperspektive", d:"Konstruktion mit Fluchtpunkt, Horizont, Fluchtlinien; Zentralperspektive (1 Fluchtpunkt) vs. Übereckperspektive (2). Kommt dem menschlichen Sehen am nächsten.", m:"m1", also:["m5"]},
  {t:"Betrachterstandpunkt", d:"Vogelperspektive = klein/hilflos · Normalperspektive = neutral/auf Augenhöhe, einbindend · Froschperspektive = mächtig/erhaben.", m:"m1", also:["m3","m5"]},
  {t:"Luftperspektive", d:"Malerisches Raummittel: In der Entfernung werden Konturen unschärfer, Flächen heller und kontrastärmer; „Sfumato“ nach Leonardo.", m:"m1", also:["m4","m5"]},
  {t:"Farbperspektive", d:"Malerisches Raummittel: Ferne „verblaut“; warm = nah, kalt = fern.", m:"m1", also:["m5"]},
  {t:"Polyvalente Perspektive", d:"Mehrere Blickpunkte gleichzeitig (Kubismus → Allansichtigkeit), Zerr- und Bedeutungsperspektive, mehrdeutige Räume (Surrealismus).", m:"m1", also:[]},
  {t:"Plastizität", d:"Erscheinung von Körperlichkeit/Dreidimensionalität, erzeugt durch Körperschatten (Halb-/Kernschatten), Schlagschatten oder Farbmodulation.", m:"m1", also:["m5"]},
  {t:"Farbmodulation", d:"Körperlichkeit allein durch Variation eines Farbtons statt Hell-Dunkel-Abstufung.", m:"m1", also:[]},
  {t:"Bildformat", d:"Hoch-, Querformat, Rondo, Quadrat, Parallelogramm – Querformat betont ein weites, natürliches Sichtfeld.", m:"m1", also:["m3","m5"]},
  {t:"Farbdimensionen", d:"Drei messbare Eigenschaften: Farbton (Richtung), Helligkeit (Tonwert), Intensität (Sättigung).", m:"m2", also:["m1","m5"]},
  {t:"Farbe-an-sich-Kontrast", d:"Itten: Gegenüberstellung reinbunter Farben.", m:"m2", also:[]},
  {t:"Hell-Dunkel-Kontrast", d:"Itten: Unterschied der Tonwerte; hervorhebend und spannungsvoll.", m:"m2", also:["m1","m5"]},
  {t:"Kalt-Warm-Kontrast", d:"Itten: Warm (Gelb → Rotviolett) gegen Kalt (Gelbgrün → Violett); spannungsvoll und belebend.", m:"m2", also:["m5"]},
  {t:"Komplementärkontrast", d:"Itten: Im Farbkreis gegenüberliegende Farben (Violett–Gelb, Grün–Rot, Blau–Orange).", m:"m2", also:["m5"]},
  {t:"Simultankontrast", d:"Itten: Optische Täuschung – das Auge ergänzt selbstständig die Komplementärfarbe.", m:"m2", also:[]},
  {t:"Qualitätskontrast", d:"Itten: Reinbunt-gesättigt gegen getrübt; auch Mittel der Luftperspektive.", m:"m2", also:["m1","m5"]},
  {t:"Quantitätskontrast", d:"Itten: Mengenverhältnis unterschiedlich großer Farbflächen; harmonisch ohne Dominanz.", m:"m2", also:[]},
  {t:"Symbolfarbe", d:"Farbe mit festgeschriebener Bedeutung; höchster Symbolrang = höchster Materialwert (Gold = göttliche Sphäre).", m:"m2", also:[]},
  {t:"Lokalfarbe", d:"Gegenstandsfarbe/Eigenfarbe – naturgetreu und sachlich.", m:"m2", also:["m5"]},
  {t:"Erscheinungsfarbe", d:"Farbe unter momentanen Lichtverhältnissen; atmosphärisch und stimmungsvoll – Schlüsselbegriff des Impressionismus.", m:"m2", also:["m4","m5"]},
  {t:"Ausdrucksfarbe", d:"Vom Gegenstand gelöste Farbe als Träger innerer Zustände.", m:"m2", also:[]},
  {t:"Autonome Farbe", d:"Farbe als Selbstzweck ohne Gegenstandsbezug (abstrakte Malerei).", m:"m2", also:[]},
  {t:"Kolorismus", d:"Farbwertbestimmtes Malkonzept – Buntheit ist das Gestaltungskonzept.", m:"m2", also:[]},
  {t:"Valeurismus", d:"Tonwertiges Malkonzept: Ton-in-Ton mit feinen Valeurs in begrenztem Spektrum; ruhig und sachlich.", m:"m2", also:["m5"]},
  {t:"Monochromie", d:"Malerei in den Tonwerten nur einer Farbe.", m:"m2", also:[]},
  {t:"Lasurtechnik", d:"Mehrere durchscheinende Farbschichten; ruhige, naturgetreue Oberflächen ohne sichtbaren Duktus.", m:"m2", also:["m5"]},
  {t:"Primamalerei", d:"Ein Schichtauftrag, deckend bis pastos, „alla prima“ in einem Gang ohne Vorzeichnung.", m:"m2", also:["m4"]},
  {t:"Pinselduktus", d:"Die sichtbare „Handschrift“ des Pinselstrichs; im Impressionismus bewusst sichtbar, bei Caillebotte weitgehend versteckt.", m:"m2", also:["m4","m5"]},
  {t:"Was-und-Wie-Probe", d:"Rechtschreibtest für Farbnamen: „Was?“ = Nomen = groß (Rot zeigen); „Wie?“ = Adjektiv = klein (ist rot).", m:"m2", also:[]},
  {t:"Bindestrich bei Farben", d:"Zwei erkennbare Farben → Bindestrich (blau-rot gestreift); Mischung → ein Wort (blaurot); Tönungen → zusammen (tiefgrün).", m:"m2", also:[]},
  {t:"Bildanalyse-Schema", d:"Rahmendaten → Beschreibung → Analyse → Interpretation.", m:"m3", also:["m5"]},
  {t:"Rahmendaten", d:"Titel, Künstler, Jahr, Ort, Maße, Format, Technik, Genre + Bildmotiv im Einleitungssatz.", m:"m3", also:["m5"]},
  {t:"Beschreibung", d:"Sachliche Nennung des Sichtbaren ohne Wertung, vom Wesentlichen zum Detail, gegliedert nach Bildbereichen.", m:"m3", also:["m5"]},
  {t:"Erster Eindruck", d:"Die subjektive Wirkung am Beginn der Analyse – wird später durch die Analyse bestätigt oder relativiert.", m:"m3", also:["m5"]},
  {t:"Analyse", d:"Schritt 2: Bildnerische Mittel benennen und mit ihrer Wirkung verknüpfen (FARBE, MOTIV, KOMPOSITION, PUNKT/LINIE/FLÄCHE, KÖRPER/RAUM/LICHT).", m:"m3", also:[]},
  {t:"Interpretation", d:"Schritt 3: Deutung aus Fakten + Rückbezug + Ikonizitätsgrad + Hintergrundwissen.", m:"m3", also:["m5"]},
  {t:"Ikonizitätsgrad", d:"Grad der Naturtreue: Stofflichkeits-, Körperlichkeits-, Räumlichkeitsillusion + anatomische, farbige, zeichnerische Richtigkeit.", m:"m3", also:["m5"]},
  {t:"Ikonografie", d:"Motiv- und Symboltradition als Deutungshintergrund (neben Zeit, Künstler, Epoche).", m:"m3", also:[]},
  {t:"Formulierungshilfe", d:"Formulierungsschatz für jede Analysephase (Wirkung, Einleitungssatz, Analyse, Deutung) – für flüssige, fachsprachliche Texte.", m:"m3", also:[]},
  {t:"Œuvre", d:"Das Gesamtwerk einer Künstlerin/eines Künstlers (nie ein Einzelbild!).", m:"m3", also:[]},
  {t:"Bildgenre", d:"Motiv- und Inhaltsgattung eines Werks: Bildnis, Landschaft, Stillleben, Historienbild, Akt u. a. – gehört in die Rahmendaten.", m:"m3", also:["m5"]},
  {t:"Bildmotiv", d:"Das Thema der Darstellung – Ausgangspunkt von Beschreibung und Analyse; die Motivwahl löst Assoziationen und Stimmungen aus.", m:"m3", also:["m5"]},
  {t:"Impressionismus", d:"Stilrichtung ca. 1860–1905: helle Palette, skizzenhafter sichtbarer Farbauftrag, Pleinairmalerei, Festhalten des flüchtigen Eindrucks, Motive des modernen Lebens.", m:"m4", also:["m5"]},
  {t:"Namensgebung", d:"Monets „Impression, soleil levant“ (1872) → Kritiker Louis Leroy, 1874, spöttische Rezension der Nadar-Ausstellung → Gruppenname „Impressionisten“.", m:"m4", also:["m5"]},
  {t:"Société anonyme", d:"„Société anonyme des artistes peintres, sculpteurs, graveurs“ – der von Ausgestellten selbst gewählte Name ihrer Ausstellung 1874 (30 Künstler, Atelier Nadar).", m:"m4", also:[]},
  {t:"pochade / étude", d:"Pochade = flüchtige Eindrucks-Skizze; étude = genaue, langsame Ausarbeitung. Monet machte die pochade zum ausgestellten Kunstwerk.", m:"m4", also:[]},
  {t:"Pleinairmalerei", d:"Freilichtmalerei en plein air – unter den technischen Voraussetzungen (Farbtuben, Staffelei, Grundierung) erst möglich.", m:"m4", also:["m5"]},
  {t:"Palettenaufhellung", d:"Kernmerkmal: helle, reine Farben; Vermeidung von Schwarz; Abwendung vom Chiaroscuro; Chromgelb & Bleiweiß statt Elfenbeinschwarz/Bitumen.", m:"m4", also:["m5"]},
  {t:"virgulisme", d:"Die kommaartigen, lockeren Kurz-Pinselstriche der Alla-prima-Malerei, die sich erst im Auge des Betrachters mischen.", m:"m4", also:[]},
  {t:"Alla-prima-Malerei", d:"Direktes, skizzenhaftes Malen ohne Vorzeichnung in einem Arbeitsgang.", m:"m4", also:["m2"]},
  {t:"Offene Form", d:"Auflösung scharfer Konturen zugunsten der Farbe; fordert die Sehleistung und Mitarbeit des Betrachters.", m:"m4", also:["m5"]},
  {t:"Anschnitt", d:"Bildrand schneidet durch Figuren/Objekte – Komposition des Ausschnitthaften und Zufälligen; Schnappschusseffekt.", m:"m4", also:["m5"]},
  {t:"Gegenwartsbezug", d:"Motive des modernen Lebens statt Historie/Religion; keine politische Sozialkritik; Ablehnung von Salonmalerei und Akademismus.", m:"m4", also:["m5"]},
  {t:"Haussmannisierung", d:"Modernisierung von Paris unter Napoleon III. – die neuen Boulevards als Bildthema des Impressionismus.", m:"m4", also:["m5"]},
  {t:"Serienmalerei", d:"Dasselbe Motiv in wechselndem Licht (Monet) – Bildthema ist die Lichtstimmung selbst.", m:"m4", also:[]},
  {t:"Riviere-Zitat", d:"„Einen Gegenstand um der Farben willen zu malen und nicht um seiner selbst willen“ – Form schlägt Gegenstand.", m:"m4", also:[]},
  {t:"impressionistische Plastik", d:"Malerisch-skizzenhafte Bildhauerei: Licht, Bewegung, „Buckel und Höhlungen“ (Rodin, Claudel, Degas, Rosso).", m:"m4", also:[]},
  {t:"Degas", d:"Edgar Degas (1834–1917) – Führer der Figurenmaler, die sich in der Akademie-Tradition sahen und den Begriff „Impressionismus“ ablehnten; zugleich in der Plastik wichtig.", m:"m4", also:[]},
  {t:"Momentanheit", d:"Das Festhalten des flüchtigen, unmittelbaren Seheindrucks (inkl. Atmosphäre) – ohne Detailtreue, gegen erzählende Historienmalerei.", m:"m4", also:["m5"]},
  {t:"Technische Voraussetzungen", d:"Synthetische Farben in Zinntuben, transportable Staffeleien, vorgegründerte Keilrahmen-Leinwände, Sonnenschirm – die Basis der Freilichtmalerei.", m:"m4", also:["m5"]},
  {t:"Caillebotte Rahmendaten", d:"Straße in Paris an einem regnerischen Tag · 1877 · Öl/Leinwand · 212,2 × 276 cm · Art Institute of Chicago.", m:"m5", also:[]},
  {t:"Doppelte Bildwirkung", d:"Trist/kühl/isoliert UND dynamisch/lebendig/alltäglich – der Zwiespalt des Bildes.", m:"m5", also:["m3"]},
  {t:"Fazit Caillebotte", d:"Zwischen Naturalismus (detailgenau, unduktuslos) und Impressionismus (Motiv, Komposition, lichte Palette) – „noch“ naturalistisch, aber impressionistisch im Sehen.", m:"m5", also:["m4"]}
];

/* Karten-IDs erzeugen */
DATA.cards.forEach(function(c,i){ c.id = c.m + "#" + i; });

/* Statistik der Karten pro Modul (für UI) */
DATA.cardsPerModule = DATA.modules.reduce(function(o,m){ o[m.id] = DATA.cards.filter(function(c){return c.m===m.id;}).length; return o; }, {});
